INSERT INTO `service_reviews` (`id`, `service_id`, `user_id`, `booking_id`, `rating`, `title`, `comment`, `status`, `created_at`, `updated_at`) VALUES
	(1, 3, 5, 10, 5, NULL, 'Loved the beach view and the cozy rooms. Staff were warm and helpful.', 'published', '2026-10-08 02:00:00', '2026-11-15 04:36:46'),
	(2, 3, 7, 11, 4, NULL, 'Great value for the price. The villa felt like home. Will come back!', 'published', '2026-10-03 02:00:00', '2026-11-15 04:36:46'),
	(3, 3, 3, 12, 5, NULL, 'Clean, comfortable, and peaceful. Perfect for a weekend getaway.', 'published', '2026-09-28 02:00:00', '2026-11-15 04:36:46'),
	(4, 3, 11, 13, 4, NULL, 'Beautiful property and friendly hosts. Highly recommended.', 'published', '2026-09-23 02:00:00', '2026-11-15 04:36:46'),
	(5, 6, 4, 15, 4, NULL, 'Spacious room and very clean. The air conditioning worked great.', 'published', '2026-11-06 02:00:00', '2026-11-15 04:36:46'),
	(6, 6, 6, 16, 5, NULL, 'Quiet at night and just a short walk to the beach. Would stay again.', 'published', '2026-11-02 02:00:00', '2026-11-15 04:36:46'),
	(7, 7, 8, 17, 5, NULL, 'Comfortable beds and helpful staff. Good value for the price.', 'published', '2026-11-06 02:00:00', '2026-11-15 04:36:46'),
	(8, 7, 9, 18, 4, NULL, 'The room was tidy and the view was lovely. Enjoyed our stay.', 'published', '2026-11-02 02:00:00', '2026-11-15 04:36:46'),
	(9, 8, 10, 19, 5, NULL, 'Easy check-in and a relaxing atmosphere. Recommended.', 'published', '2026-11-06 02:00:00', '2026-11-15 04:36:46'),
	(10, 8, 12, 20, 4, NULL, 'Plenty of space for the family and the kids loved it.', 'published', '2026-11-02 02:00:00', '2026-11-15 04:36:46'),
	(11, 9, 13, 21, 5, NULL, 'Bright, airy, and close to everything we needed.', 'published', '2026-11-06 02:00:00', '2026-11-15 04:36:46'),
	(12, 9, 14, 22, 4, NULL, 'Peaceful stay with friendly hosts. We will be back.', 'published', '2026-11-02 02:00:00', '2026-11-15 04:36:46'),
	(13, 5, 14, 23, 5, NULL, 'Rented the whole villa for a family reunion and it was perfect. Plenty of room for everyone.', 'published', '2026-11-07 02:00:00', '2026-11-15 04:36:46'),
	(14, 5, 7, 24, 5, NULL, 'The shared spaces were great for our group. Clean rooms and a very helpful caretaker.', 'published', '2026-11-04 02:00:00', '2026-11-15 04:36:46'),
	(15, 5, 13, 25, 4, NULL, 'Ideal for a big group. We loved the veranda and the short walk to the shore.', 'published', '2026-11-01 02:00:00', '2026-11-15 04:36:46'),
	(16, 5, 4, 26, 5, NULL, 'Everything we needed for a weekend with friends. Would book the whole villa again.', 'published', '2026-10-29 02:00:00', '2026-11-15 04:36:46'),
	(17, 5, 3, 27, 4, NULL, 'Spacious and comfortable. The kitchen and dining area made group meals easy.', 'published', '2026-10-26 02:00:00', '2026-11-15 04:36:46'),
	(18, 5, 12, 28, 5, NULL, 'Great value for a large group. The beach is just a few steps away.', 'published', '2026-10-23 02:00:00', '2026-11-15 04:36:46');
